module bnd_ff #(parameter [0:0] INIT = 1'b0) (input wire CLK, input wire D, output wire Q);
`ifdef YOSYS
    generate if (INIT) begin : s
        DFFNS ff (.CLK(CLK), .D(D), .SET(1'b0), .Q(Q));
    end else begin : r
        DFFN ff (.CLK(CLK), .D(D), .Q(Q));
    end endgenerate
`else
    reg q = INIT;
    always @(negedge CLK) q <= D;
    assign Q = q;
`endif
endmodule
